export type ParsedClaimCnftV2Instruction<
  TProgram extends string = typeof MALLOW_GUMBALL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Anyone can claim the item for the recorded buyer. */
    payer: TAccountMetas[0];
    /** Gumball machine account. */
    gumballMachine: TAccountMetas[1];
    authorityPda: TAccountMetas[2];
    /** Seller of the cNFT. */
    seller: TAccountMetas[3];
    /** Buyer of the cNFT (recorded at draw). Receives the leaf. */
    buyer: TAccountMetas[4];
    treeConfig: TAccountMetas[5];
    /**
     * `assert_config_line` (which compares the derived asset id to the stored
     * config-line mint).
     */
    merkleTree: TAccountMetas[6];
    coreCollection?: TAccountMetas[7] | undefined;
    logWrapper: TAccountMetas[8];
    compressionProgram: TAccountMetas[9];
    bubblegumProgram: TAccountMetas[10];
    systemProgram: TAccountMetas[11];
    eventAuthority: TAccountMetas[12];
    program: TAccountMetas[13];
  };
  data: ClaimCnftV2InstructionData;
};

export function parseClaimCnftV2Instruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedClaimCnftV2Instruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 14) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 14,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === MALLOW_GUMBALL_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      gumballMachine: getNextAccount(),
      authorityPda: getNextAccount(),
      seller: getNextAccount(),
      buyer: getNextAccount(),
      treeConfig: getNextAccount(),
      merkleTree: getNextAccount(),
      coreCollection: getNextOptionalAccount(),
      logWrapper: getNextAccount(),
      compressionProgram: getNextAccount(),
      bubblegumProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getClaimCnftV2InstructionDataDecoder().decode(instruction.data),
  };
}
